import json

with open('data/modern-translation/t1251_part4.json', 'r', encoding='utf-8') as f:
    modern = json.load(f)

# 段141
modern[141] = "【十二印法起始】於是天等全都承受教命，被授予勝地，合掌聽聞受持，於此大王開始宣說從十二印法、咒開始的各種印真言法印。首先安住慈悲三昧，行者開始結印法。第一個印，是大金剛合掌。真言說：「曩謨三滿多縛日羅赦󱂷梨𫄅吽（二合）」「接著是面印。【义解】本段講一切天眾都領命護法，天王開始宣說十二印法：首先要求行者入慈悲三昧，第一印是大金剛合掌（總印），給出對應真言，隨後引出面印。"
# 段142
modern[142] = "【面眼鼻耳印】蓮花合掌。真言和前面一樣。「接著是眼印。左右手各作拳，兩個地指（小指）豎立，在兩眼旁旋轉。真言和前面一樣。「接著是鼻印。左右手的地指、火指各交叉豎立，兩個水指（無名指）指尖合在一起，二風指（食指）作成三角形站立，放在鼻前。真言和前面一樣。」「接著是耳印。左右手的地水火風四指分開豎立，大拇指收進掌內，放在左右耳邊。【义解】本段依次講面印（蓮花合掌，同前真言）、眼印（握拳豎小指，在眼邊旋轉）、鼻印（地火交叉、水合、風三角，置鼻前）、耳印（四指開豎、拇指入掌，貼耳邊），都是十二印中的莊嚴支分印，真言通用總印真言。"
# 段143
modern[143] = "【口舌肩腰印】真言和前面一樣。「接著是口印。左右手的地指、風指交叉豎立，左右手的水指、火指都橫臥，二空指如柱豎立，觀想牙齒、對著口，念我金剛（金剛就是一切不能破壞）身。真言和前面一樣。「接著是舌印。左右手的風指、空指指尖合在一起，其餘三指並列豎立，二手很好地並立，觀想伸入口中。【义解】本段接續十二印：口印（地風交叉、水火橫、空指柱，對口觀牙齒、金剛身）、舌印（風空合、三指並立，觀入口中），莊嚴口與舌支分。"
# 段144
modern[144] = "【舌肩腰乳脇印】真言和前面一樣。「接著是兩肩印。左右手五指好好豎立，分別放在肩上，指尖朝向口的方向，誦真言和前面一樣。「接著是腰印。左右手的火指（中指）向內彎二三節，下面各指的指尖和兩大拇指合在一起，在腰邊旋轉。真言和前面一樣。「接著是兩乳印。左右手的地指、空指，四個指尖並立作成三角形寶形，左右手的水、火、風指分散放在兩乳上。【义解】本段繼續十二印：肩印（五指豎立放肩上）、腰印（火指內彎、指拇合，腰際旋轉）、兩乳印（地空合三角寶形，餘三指散放乳上），莊嚴肩、腰、乳支分，真言同前。"
# 段145
modern[145] = "【脇座印與功德】真言和前面一樣。「接著是左右脇印。二手結內縛，左右手地指尖對立，在兩脇邊旋轉。真言和前面一樣。「接著是半座印。右手五指並立，稍微彎曲如半蓮華形，觀想蹲踞。它的真言和前面一樣（此是八大曼荼羅）。「全部依靠這十二印法，（聖眾）就會如影隨形到持法人的處所，晝夜無間守護持法人，消滅無量災難病患，獲得無量福德自在以及官位。【义解】本段完成最後兩個印：左右脇印（內縛、小指對立，脇邊旋轉）、半座印（右手五指微屈如半蓮，觀蹲踞）；總結十二印的功德：聖眾恆常守護，消災治病，得福得官。"
# 段146
modern[146] = "【三種護摩火壇】」那時宣說護摩的作法樣式。「如果有眾生被家人厭魅、咒詛，想要脫離這個患難，應當使用護摩法，用這個法調伏諸惡事。另外想要消滅一切病患以及各種惡事，也應用這個護摩法。如果想要用這個法，首先說壇的樣式有三種火壇：一是息災、二是增益、三是調伏（降伏）。【义解】本段進入護摩法的具體講解：首先說明護摩的用途——除厭魅咒詛、消病患惡事；三種護摩對應三種事業：息災（扇底迦）、增益（補瑟徵迦）、降伏（阿毘遮盧迦）。"
# 段147
modern[147] = "【息災增益壇式】延命法攝在息災法中，一切求願的事，以及敬愛法，都攝在增益法中，相應降伏法就是降伏事業。首先息災壇是圓形，壇口直徑一肘，總方圓一肘。火壇的花邊寬三指，下面地壇表面的圓緣寬七指。四方安放蓮華，四角安放三鈷杵。火爐在阿闍梨前面是花台，底部作十字形，深度七指。【义解】本段說明事業攝屬：延命屬息災，敬愛、諸願求屬增益，調伏怨敵屬降伏；隨後講息災火壇的形制：圓形，尺寸（口徑1肘，花緣3指，地緣7指，深7指），莊嚴（四方蓮華、四角三鈷、底十字）。"
# 段148
modern[148] = "【增益降伏壇式】增益壇，是四方四角形，壇口直徑一肘五指，花邊寬三指，地緣寬七指，深度半肘。四方安放三鈷杵，四角安放花，前面底部是十字杵，伏底是十字羯磨。接著是降伏壇，首先在四角的地壇是一肘七指，然後上面作三角壇，花緣是三角形口。三角口的直徑是一肘二指，方寸和前面一樣，深度依照前面所說。【义解】本段講增益壇形制：方形，尺寸（口徑1肘5指，花緣3指，地緣7指，深半肘），莊嚴（四方三鈷、四角花、底十字羯磨）；降伏壇形制：下方方壇，上方三角火壇，尺寸（三角口徑1肘2指，深度同前）。"
# 段149
modern[149] = "【護摩壇色與降伏印】三角位置安放獨鈷杵，二方安放獅子面，壇的基部在蓮台上。息災壇是白色，衣服等一切物品都用白色。敬愛法也是這樣，如果是求所願就用青色。增益法用黃色，壇的顏色也是這樣。降伏壇是紺色，衣服等一切物品都用這個顏色，必定能調伏。如果要做護摩，首先用最勝太子降伏大法印。【义解】本段補充降伏壇的莊嚴（三角獨鈷、二方獅子面、蓮台基），以及三種壇的對應顏色：息災/敬愛白，求願青，增益黃，降伏紺；隨後引出護摩用的最勝太子降伏大法印。"
# 段150
modern[150] = "【最勝太子降伏印】先左手拿大刀，右手握拳，觀想向四方打擊。如果沒有大刀，也可以用內印。先二手合掌，二地指（小指）分開三寸左右，二大拇指並列如獅子耳朵，這就是大降伏印。行人至心觀想，只要這個印一結，一切所要做的事都能成就。如果是加持各種物品的法事，行者只要體會意思用這個印明就可以。【义解】本段講最勝太子降伏印：外印是左手持刀、右手握拳打四方；內印是合掌、小指開3寸、大指並如獅耳；這個印是降伏大法的總印，結之即能成辦降伏、加持諸物。"
# 段151
modern[151] = "【降伏印真言】明說：「唵縛日羅（二合）擬首耶（一）　婆多知也（二合）（二）　娑婆知耶（二合）那（三）　矩馱矩馱（四）　阿羅馱阿羅馱（五）　蘇嚕儞蘇嚕儞（六）　蘇知嚕知嚕儞唅吽（七）　泮（八）　吒」「用這個真言印加持之後，四方世界所有的天地神等，不安的都會怖畏被縛。【义解】本段給出最勝太子降伏印對應的真言，宣說此印咒的威力：加持之後一切天地善神安穩，惡神惡魔都怖畏被縛。"
# 段152
modern[152] = "【行步與難相觀】然後行者以解脫心，隨自己的心結印。毘沙門天王行步真言說：「唵步利（一）　唵矩味唅吽（二合）泮吒（引）」「如果想要度過災難，首先要作佉羅都盧（障難形）：首先生老病死，形狀像雲色蛇形。如果有惡人誹謗難為持法人，種種形狀如果是魚血，如果又有行法者的血，用這些材料全部作成那個形狀，這名叫究竟難。【义解】本段講解脫心行步，給出行步真言；隨後講降伏災難的作形法：把生老病死、惡人誹謗、血光等災難都觀成/作成對應的形相（雲色蛇、魚血形等），名為究竟難，用來代表所要降伏的障礙。"
# 段153
modern[153] = "【降伏難形作法】如果是魔、一切災難就作成大鬼形，如果是咒詛諸災難，就作成大惡蛇形。如果有惡人誹謗持法人，這樣的人就應當作他的人形，再觀想進入心裡名為盡。如果行者隨心把這些災難都作成形象，在佛塔、僧坊或者行法的地方，先跨過這些難形，再用前面的印加持這些形象：先將印的二小指、無名指互相鉤向內直立，二中指和二大拇指向外橫伸，二風指放在掌中，就成為護身和加持的印。【义解】本段講不同障礙對應的形相：魔災作大鬼形，咒詛作大蛇形，惡人作本人形；加持形相的方法：跨過難形，用鉤指印加持，這個印同時也是護身印。"
# 段154
modern[154] = "【降伏一切惡人印】一切降伏印真言說：「曩謨奢多羅耶（一）　南無（二合）三勃陀（二）　阿婆耶多羅耶（三）　南無婆多婆奈曳薩嚩賀（引）」「如果要降伏一切惡人、各種不祥災難、外道惡比丘等，都要一一作成他們的形體，用這個印明加持。【义解】本段給出降伏一切惡人、外道、災難的專用真言，用法是先作對方/災難的形相，再結印誦咒加持。"
# 段155
modern[155] = "【金剛橛降伏法】還要用骨角製作金剛橛，長六寸或五寸，還要製作法用的盤子，方九寸、七寸或五寸，盤面上都畫上獅子王。四個角畫惡形惡鬼，中間是十字大刀朝下。隨心所欲作惡形高三寸，對準護摩壇前面，把形體橫放。先用兩根橛打在它左右脇加持，再用兩根橛打在兩腳立住，用一根橛打在它心上，各加持一百零八遍完畢，那個惡形就被摧碎如微塵。【义解】本段講極重降伏法的金剛橛用法：作方盤畫獅子、惡鬼、十字刀，作惡人形高三寸橫放壇前，用五根金剛橛分別打在左右脇、雙腳、心臟位置，各加持108遍，將惡形摧碎如塵，用來降伏極重怨敵魔障。"
# 段156
modern[156] = "【七日護摩降伏】把碎末放在手掌中，念著名字丟入火中。這樣丟完之後，就把那個盤子密藏在阿闍梨的座位下面。這樣的一個盤子，要用兩種木來做降伏法：佉多羅木，或者跋沙羅佉木，或者花木等來作盤。這樣做七日七夜護摩，室內的災難全都消滅。如果是人間的惡事、惡人，都會在七中死亡，被降伏隨從。【义解】本段接續金剛橛降伏法：將摧碎的惡形粉末念名投入火中焚燒，盤子藏在阿闍梨座下；用指定木材作盤，護摩七日，能消室內災，令惡人七日內被降伏，甚至死亡。"
# 段157
modern[157] = "【成就驗相與揀擇】如果這樣行者發起慈悲心，行息災法，就會恢復原狀。這個自在大法不要隨便傳授他人。如果修法時有天地喜悅的瑞相，或者行者夢中見到好相。又或者有虛空中的聲音說：『你所修的法全都成功、都成就了。』不要再生懷疑。如果生起少許疑念，就會失去大神驗。如果沒有空中的聲音，也沒有好相，但出現大空、大雨、大雲、大雪失時節，發出聲音，大風從四方吹來，這些相也都是成就相，更不要生疑。【义解】本段講修法成就的驗相：感應瑞相、好夢、空聲授記，或者大風大雨大雪等反常天相，都是成就的標誌；強調千萬不能生疑，生疑即失驗；此法極秘，不可輕傳非人。"
# 段158
modern[158] = "【阿闍梨三品分別】這些都隨阿闍梨的心意，只要這些相顯現，這個人就名叫摩訶娑阿佉梨（大阿闍梨）。阿闍梨有三種：有這些大異相的人，名叫摩訶娑阿佉梨；另外在修法上決定有大神驗的人，名叫阿闍梨；另外對於法有信心的人，名叫持法者。這些條件全部具足的人，名叫摩訶阿那闍梨（無上阿闍梨）。【义解】本段將阿闍梨（傳法師）分為三品：大阿闍梨（現大異相）、普通阿闍梨（修法有靈驗）、持法者（有信心）；三者具足為無上阿闍梨，揀擇師資的標準。"
# 段159
modern[159] = "【伴侶揀擇標準】這些相都不具足的人，名叫摩訶嚩被者（無驗行人）。至於不依法、不通達世間出世間法、沒有福德、沒有方便的人，名叫退陀佉那（壞法者），不能做阿闍梨。選擇同行伴侶，首先要看他三種堪能：第一有福性、第二通達世間出世間法、第三心意端正、戒律威儀如法。這些都具足，才名叫善伴侶。【义解】本段揀擇不合格的行人（無驗、壞法者）不能為師；同時講選擇共同修法伴侶的標準：有福報、通達世出世法、戒律威儀清淨，三者具足才可為伴。"
# 段160
modern[160] = "【護摩般若火義】如果是沒有福德的伴侶，他行法就算看起來像成就，實際上也不會成就，因為天王不接受。只有至心修佛法，沒有不達到的。貧窮的人福德就是這樣。阿闍梨要觀察選擇伴侶。這三德具足的人，名叫大伴侶。另外行者應當做護摩的時候，要以般若智火為火，以一切眾生的罪業、煩惱、業障為薪柴。【义解】本段說明無福伴侶修法難成就，必須選擇三德具足的同伴；同時揭示護摩的真實義：不是燒世間火，而是以般若智為火，燒盡眾生煩惱罪業，是護摩的內在意義。"
# 段161
modern[161] = "【護摩火印真言】這個火不是天火、地火、人火、龍火神火、木火、石火、自然火，只是如來最秘密的般若心智火。點燃火的時候，先用這個印加持火、加持木柴，就會成為炎輪。印相是左右合掌，左中指貼右手大拇指尖，右中指又貼左手大拇指尖，兩個無名指在掌中節背後彎曲，二風指、二小指都直立指尖相柱。【义解】本段進一步闡明護摩火是般若智火，不是世間諸火；講加持火與木柴的印相結法，加持後火成為智慧炎輪。"
# 段162
modern[162] = "【火印真言與魔難相】真言說：「唵（一）　多近智（二）　娑婆訶（引）」「如果行者受持這個法，剛開始的時候會有各種天等魔障顯現，首先要把它們的樣子一一按照天等所說的觀念清楚，行者要發大心。如果聽到瞋怒的聲音，正東方下起大雨雷電來迷惑行者，應當知道這是帝釋天的魔難。東南角出現大色大人相，又像日光全部消失，應當知道這是火天王的魔難。【义解】本段給出火印對應真言；隨後講修法過程中會出現的各方魔難：帝釋難（東方雷雨）、火天難（東南大人相、日光滅），教行者辨識魔相不被迷惑。"
# 段163
modern[163] = "【八方魔難辨識】南方現出死屍形狀，又發出極大恐怖的高聲叫喚，手執大刀割人的鼻子，手拿髑髏裝人血喝，頭上火焰燃燒，應當知道就是焰摩天的魔難。西南角出現兩堆屎尿污穢的尊像，現各種極恐怖的形狀，就是羅剎難。西方雷雨大作令世界不安，這是龍難。西北方颳起大惡風，好像一切眾生都死了，乃至覺得自己也要死了，就是風神的魔難。【义解】本段繼續辨識八方魔難：南方焰摩天難（死屍、大刀、飲血、火髮），西南羅剎難（屎尿穢像），西方龍難（雷雨不安），西北風天難（大惡風、死想），教行者一一辨別。"
# 段164
modern[164] = "【上下魔難與成就相】北方有大藥叉以及女夜叉來惱亂行者，就是我（迦陀野）的難。東北角出現象頭、豬頭、狗頭的異形，各個拿著火，應當知道就是伊舍那天王的魔難。上方現出諸天等現大威德自在相，應當知道是上方天等的魔難。下方大地震動以及裂開，就知道是下方天等的魔難。行者應當知道這是將要成就時的魔難。【义解】本段接續魔難辨識：北方藥叉難（本尊自身試驗），東北伊舍那天難（異形獸頭持火），上方天難，下方地天難；點明這些都是即將成就前的考驗，不是真實災難。"
# 段165
modern[165] = "【降魔方法與護摩請聖】只要大空中間顯現（本尊光明），就應當知道是成就相。如果是在某個方向某個角出現，就觀察是那個方向的成就相。另外這就是大德成就相。如果是在夢中見到，也應當知道這是大法成就相。行者遇到這些大難顯現的時候，就念大日、觀世音等菩薩，當即就會現吉祥相。如果一切鬼神等懷有惡意，想要擾亂持法者顯現各種難惡事，行者就結手印。【义解】本段講成就相：空中現光明、夢中見瑞相，就是成就；遇到魔難時稱念大日、觀音菩薩即得吉祥；惡鬼神擾亂時立即結降伏手印。"
# 段166
modern[166] = "【縛魔手印與請聖】縛鬼神降伏手印：兩手合掌，小指、無名指各自屈入掌中，二中指指尖相柱豎立，二大指尖各自相靠，二大拇指疊在二大拇指上。真言說：「唵迦陀野吽泮吒」如果要做護摩的時候，首先請火天，供養印真言和常法一樣。接著請七曜眾的印真言，如果用大日如來五字真言；【义解】本段講降伏擾亂鬼神的專用印（合掌、小指名指入掌、中指相柱、拇指相疊）與短咒（六字吽迦陀野泮吒）；隨後講護摩的正式流程：先請火天（如常印明），再請七曜、大日如來。"
# 段167
modern[167] = "【請諸尊就座印】一切請召印明，如果用各個本尊本來的威儀印明。普通請界會印：二手結內縛，二風指（食指）豎立，二空指入內，用風指隨著「索縛賀」的聲音來去招動。真言說：「曩謨三滿多菩馱南（一）　阿多野吽（二）　索嚩賀」「就座印。「二手結金剛拳，左手背放在右手背上互相背靠，二地指（小指）在背後交叉豎立，風指也交叉豎立，拍打壇上。【义解】本段講通用的請聖印（內縛、豎風指、空入掌、招動）與真言，用來普請曼荼羅全體聖眾；接著講聖眾就座印（金剛拳、手背相靠、小指食指交叉、拍壇），令聖尊穩固安座。"
# 段168
modern[168] = "【諸天請送印】真言說：「唵嚩日羅佉吽（吽）」「接著拳華真言說：「唵吽」「請諸天等真言說：「唵嚩日羅（二合）婆多野曳枳素婆呵」如果要送諸天，用各個真言的拳送印，那個就座印各風指分開做來去動作。真言說：「唵嚩日羅（二合）佉多野吽索婆賀」【义解】本段依次給出就座印真言、拳華真言（單字吽）、請天真言，以及奉送諸天的印（風指分開擺動）與真言，完成請聖→就座→送聖的基礎印明。"
# 段169
modern[169] = "【請文與禮敬偈】如果要做護摩供養，還要誦請文說：「奉請（某方某天王）降臨我這個供養處所，願垂納受。」這樣的偈句，拿著香爐至心勸請，諸天聖者就全都來聚集到壇所。曼茶羅聖眾都請完之後，以至誠心作禮而唱這樣的話。偈說：「大悲救世尊，善導一切智，福持功德海，我今稽首禮。【义解】本段講護摩供養的口頭請文格式（奉請某方天王降臨納受），拈香至心勸請；請聖完畢後說禮敬偈，頂禮大悲世尊、智慧導師、功德海。"
# 段170
modern[170] = "【忿怒尊禮與善來偈】大力忿怒尊，善哉持明王，降伏難伏者，我今稽首禮。」「這樣禮拜完了，就誦善來聖者偈：「善來尊者，愍我等故，降臨道場。復垂哀愍，當就此座，受微獻供。大悲哀愍，成本願故，而見道場，悲我所能。【义解】本段繼續禮敬偈，頂禮大力忿怒持明王（穢跡金剛），能降伏難調伏眾生；隨後誦善來偈，歡迎聖尊降臨道場、就座接受微供，哀愍行者、成滿本願。"
# 段171
modern[171] = "【梵本與奉送偈】」「梵本說：「縛樹伽羅佉㝹野」「奉送偈說：「曩禰多尼蓮華合」「成就護摩阿毘遮盧迦一切成就忿怒金剛真言說：「唵虎魯虎魯戰拏里摩嶝淣（枳反）莎縛訶」「諸天瞋怒成就護摩真言說：「唵枳里枳里跋曰羅矩嚕馱吽」【义解】本段給出梵本請聖短咒、奉送聖眾的偈與印（蓮華合掌）；隨後給出降伏護摩（阿毘遮盧迦）忿怒金剛真言、諸天降伏瞋怒成就真言，分別用於不同的降伏事業。"
# 段172
modern[172] = "【傳法禁戒與行者安樂】「行者這個印真言絕對不可以傳給惡行修人，如果傳了法就會全部滅盡。如果有人護摩供養法印至心奉供，如果起了其他雜念，法就不會成就。如果這個法的法師做惡律儀、行外道等事業，百日的功德草木一天之內就會滅盡無餘。如果行善心、守律戒威儀，百日的功德草木一天之內就全部圓滿。【义解】本段講護摩法的傳法禁戒：不可傳給惡行人、修法不可起雜念、法師不可行惡律儀，否則功德盡失；持戒行善則功德迅速圓滿。"
# 段173
modern[173] = "【護摩木與供品】這個教法的行人不需要斷食，如果讓身體受苦，我迦陀的身體也會跟著苦。和我一同苦，我就會賜予安樂，加上天的威光，要讓行者身體安樂，不要讓他辛苦。如果我這樣的誓願成了虛語，我就更不成正覺，也不回到本城。另外護摩用七種木：一金剛佉木、二佉多娑木、三毘鉢羅多木、四毘鉢羅藏木、五時草、六堅壽木、七常榮𮏂𮑔等。【义解】本段說明修法不需要苦行斷食，天王不忍行者受苦，會令行者安樂，否則違背誓願不成佛；列出護摩專用的七種木材，分別對應不同的祈願。"
# 段174
modern[174] = "【供品與木的用途】用這些木，就能成就護摩。還要用米、五穀、胡麻、芥子、赤芥子、白芥子、紫子飯粥五合。鹽、油，還要用酢、酒、酥、蜜、酪。紫子要多用，一次放七粒、或者五粒、三粒、一粒，這是一切物中最相應的物品，是一切願成就的種子，從中出生一切願望，堅壽木。【义解】本段列出護摩需要的各種供品：米穀、胡麻、三色芥子、紫子（最重要，是成就種子）、鹽油酢酒酥蜜酪；點明堅壽木對應堅固壽命。"
# 段175
modern[175] = "【七木各自功能】念著為了除去眾生黑暗、給予光明，就用常榮木；念著讓施主安穩，就用金剛佉木；念著讓施主身體常堅固，就用毘鉢羅多木；念著施主的願望快速成就，就用毘鉢羅藏木。念著我（天王）、行者以及道場都得到清淨愛樂，就用佉多娑木。並且葉子是降伏相，就用時草。福德相，就用𮏂𮑔阿多佉木。【义解】本段詳細說明七種護摩木各自對應的功能：常榮木→施與光明，金剛佉→施主安穩，毘鉢羅多→身體堅固，毘鉢羅藏→速成諸願，佉多娑→清淨愛樂，時草→降伏，𮏂𮑔→福德。"
# 段176
modern[176] = "【護摩形相用途】這些全部都是大降伏的觀想，行者要一一了知。還要做人形五個、鬼形三個、鳥形三個。人形，代表五種大鬼魔相。鬼形代表不成事業的神。鳥形代表年歲中的不祥惡事和惡人。行者就這樣心念做護摩。如果是沙彌、童子形、還沒有得戒的人，做七日護摩供養，就能得戒。如果被盜賊偷走財寶，也是做七日護摩供養。【义解】本段講護摩時作形相的方法：5人形表五大魔，3鬼形表障礙神，3鳥形表歲惡人；以及不同祈願的護摩時限：求戒（沙彌童子）7日，求盜物歸還7日。"
# 段177
modern[177] = "【盜物與誹謗處理】如果是正在被盜的事，做七日護摩供養，把丟失的東西做成形狀，安穩時焚燒，用忿怒眼觀想本尊，誦丟失物品的名字，再用自己的血和芥子打到火中，就會成就。如果有同伴主人之間出現惡言誹謗的事，就做出人形，把血塗在那人像的眼睛上放在盤中，用刀切了丟進火燒，同時燒寫有名字的紙，如果是實事自然就會息災。【义解】本段講特殊事項的護摩方法：追盜需7日，作失物形、忿怒觀、血芥子投火；解決誹謗口舌要作人形，塗血眼、刀切後火燒，實有冤情自然息災。"
# 段178
modern[178] = "【惡人惡口懲罰】如果是有人故意惡意誹謗、造謠生事，那個人七日之內就會遭遇大難，或者身命不全，全都被諸天神等降伏。心中生起一場大難，死後墮入地獄，現世就會舌頭墮落。丟失的東西就會回來，如果聽說東西被別人、有異心的人拿去了別的地方，都會讓他拿回來。東西分成三份：一份供三寶、一份布施並自己斷事，一份給那個盜賊讓他離開。【义解】本段講誹謗惡人的惡報：7日內遭大難、現世舌爛、死墮地獄；失物回歸後分三份：三寶、斷事、盜人，令其離去，發慈悲心不趕盡殺絕。"
# 段179
modern[179] = "【慈悲止惡與惡人報】那人命在旦夕的時候，就發慈悲意，就像保全自己的性命一樣。如果這個持法人，遇到惡人誹謗的事，（惡人）現世就會舌頭斷、手腳折斷、身意顛倒，再也沒有實心，諸天全都捨離他，斷除他的性命。如果是斷他在人世的福分，或是斷他的大願，或是斷他一類結緣大眾的若干福分以及他的命根。【义解】本段講在惡人將要受報時，行者要發慈悲心留其性命；但如果惡人堅持惡意不悔改，現世就會受殘疾、顛狂、諸天捨離、死亡的報應，折福折壽。"
# 段180
modern[180] = "【惡人結局與護法】如果不斷他的命，他也會長久貧窮，遭遇刀、鐮、輪、弓、箭、國王的災難。八大世界的聖眾觀世音菩薩等全都捨離這個人，還有哪個護法天會對他發慈悲心？行者就恢復本來的狀態。如果這樣違背弘誓，就不配叫護法天。（護法）對於持法者絕不會有少許惡念。如果是放逸的比丘、沙彌、童子，見到我一面十手的形相，全部都會被打碎，如同惡形鬼形，如同地獄中被截斷的身體被水流沖到別處，諸天鬼神都會這樣打擊驅除懲罰，永遠不再讓我見到。【义解】本段講惡人就算不死也會長貧、遇刀兵王難，聖眾捨離；同時說明護法天永遠不會加害如法行者，但對破戒放逸的僧眾、童子，本尊會現忿怒十手相打碎懲罰，令其墮落。"

